const $=s=>document.querySelector(s);
const cfg=window.ENTRELADOS_CONFIG||{};
const live=Boolean(cfg.supabaseUrl&&cfg.supabaseAnonKey);
let db,user,room,profile,channel,poll,tick,demoTasks=[],busy=false,sessionToken=0,lastSend=0;
const seen=new Set();
const topics=['O que você gostaria que o outro lado entendesse melhor sobre você?','Qual problema do Brasil deveria ser prioridade para todos, independentemente do lado?','Existe alguma ideia do outro lado com a qual você concorda?','Alguma conversa já fez você mudar de opinião?','Qual experiência pessoal mais influenciou sua visão política?'];let topicIndex=0;
function screen(name){for(const id of ['landing','waiting','chat'])$('#'+id).hidden=id!==name;document.body.classList.toggle('in-chat',name==='chat');$('#bottom-strip').hidden=name==='chat';window.scrollTo(0,0)}
function modal(html){$('#dialog-content').innerHTML=html;$('#info-dialog').showModal()}
$('.dialog-close').onclick=()=>$('#info-dialog').close();$('#info-dialog').addEventListener('click',e=>{if(e.target===$('#info-dialog'))$('#info-dialog').close()});
$('#how').onclick=()=>modal('<div class="eyebrow">COMO FUNCIONA</div><h2>Um encontro. Duas perspectivas.</h2><ol><li>Escolha um apelido e seu posicionamento.</li><li>Encontramos a pessoa do outro lado que está esperando há mais tempo.</li><li>Vocês têm até 30 minutos para conversar por texto.</li></ol><p>Sem alguém disponível, você aguarda na fila. Você pode encerrar quando quiser.</p>'+(live?'':'<p><strong>Esta é uma prévia.</strong> Explore o chat com mensagens de exemplo. Não há outra pessoa conectada nesta demonstração.</p>'));
$('#privacy').onclick=()=>modal('<h2>Respeito é o ponto de partida.</h2><p>Use um apelido e evite compartilhar telefone, endereço ou outros dados pessoais. Seu posicionamento serve para encontrar uma perspectiva diferente.</p><p>Não publique ameaças, ataques pessoais ou dados de outras pessoas. Você pode encerrar e denunciar uma conversa a qualquer momento.</p><p>Na versão conectada, mensagens ficam disponíveis aos participantes; denúncias são registradas para revisão administrativa. Bloquear alguém impede novos pareamentos entre vocês, dentro da mesma identidade de acesso. A política de retenção deve ser definida antes da abertura pública.</p><p>Na demonstração, nenhuma mensagem é enviada a um servidor de chat.</p>');
$('#new-topic').onclick=()=>{$('#topic').textContent=topics[++topicIndex%topics.length]};
if(live){$('#mode-label').textContent='Conexão privada · encontros de 30 minutos';$('#demo-enter').hidden=true}else{$('#wait-demo').hidden=false}
async function connect(){if(db)return;const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.49.8');db=createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);const {data:{session}}=await db.auth.getSession();if(session)user=session.user;else{const {data,error}=await db.auth.signInAnonymously();if(error)throw error;user=data.user}}
function check(error){if(error)throw error}
function showError(e){$('#entry-error').textContent=e?.message||'Não foi possível conectar. Tente novamente.'}
function stop(){clearInterval(poll);clearInterval(tick);for(const t of demoTasks)clearTimeout(t);demoTasks=[];if(channel){db?.removeChannel(channel);channel=null}}
function system(text){const p=document.createElement('p');p.className='system-message';p.textContent=text;$('#messages').append(p);scroll()}
function scroll(){$('#messages').scrollTop=$('#messages').scrollHeight}
function message(text,mine=false,at=new Date()){const el=document.createElement('div');el.className='message'+(mine?' mine':'');el.textContent=text;const stamp=document.createElement('small');stamp.textContent=new Date(at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});el.append(stamp);$('#messages').append(el);scroll()}
function receive(m){if(seen.has(m.id))return;seen.add(m.id);message(m.body,m.sender_id===user?.id,m.created_at)}
function countdown(){if(!room)return;const remaining=Math.max(0,Math.ceil((Date.parse(room.expires_at)-Date.now())/1000));$('#timer span').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;$('#timer').classList.toggle('urgent',remaining<=60);if(remaining<=300&&!room.warn5){room.warn5=true;system('Faltam 5 minutos. Que tal encontrar um ponto em comum?')}if(remaining<=60&&!room.warn1){room.warn1=true;system('A conversa termina em 1 minuto.')}if(!remaining)finish('Os 30 minutos terminaram. Que tal conhecer outra perspectiva?')}
function prepareChat(name,side){screen('chat');$('#messages').replaceChildren();seen.clear();$('#chat-ended').hidden=true;$('#message-input').disabled=false;$('#message-form button').disabled=false;$('#partner-name').textContent=name;$('#partner-side').textContent=side==='left'?'Perspectiva de esquerda':'Perspectiva de direita';$('#partner-avatar').textContent=side==='left'?'↙':'↗';$('#chat-status').textContent='';$('#demo-badge').hidden=live;$('#timer').classList.remove('urgent');system(live?'Vocês têm até 30 minutos. Uma boa conversa começa com respeito.':'Demonstração: as mensagens recebidas são exemplos, não respostas de uma pessoa real.');countdown();tick=setInterval(countdown,1000)}
async function startLiveChat(id,token){if(room?.id===id)return;const {data:r,error}=await db.from('rooms').select('*').eq('id',id).single();check(error);if(token!==sessionToken)return;room=r;const other=r.user_a===user.id?r.user_b:r.user_a;const {data:p,error:pe}=await db.from('profiles').select('nickname,side').eq('id',other).single();check(pe);if(token!==sessionToken)return;stop();prepareChat(p.nickname,p.side);channel=db.channel('room-'+r.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'messages',filter:`room_id=eq.${r.id}`},e=>receive(e.new)).subscribe();await syncRoom();poll=setInterval(()=>syncRoom().catch(()=>{$('#chat-status').textContent='Reconectando… suas mensagens permanecem na sala.'}),3000)}
async function syncRoom(){if(!room||!live)return;const id=room.id;const {data:messages,error}=await db.from('messages').select('*').eq('room_id',id).order('created_at').limit(2000);check(error);if(room?.id!==id)return;messages.forEach(receive);const {data:r,error:re}=await db.from('rooms').select('status').eq('id',id).single();check(re);if(room?.id!==id)return;$('#chat-status').textContent='';if(r.status!=='active')finish('A conversa foi encerrada. Obrigado por participar.')}
async function seek(token){const {data,error}=await db.rpc('join_queue',{p_nickname:profile.nickname,p_side:profile.side});check(error);if(token!==sessionToken)return;if(data.room_id){await startLiveChat(data.room_id,token);return}$('#wait-copy').textContent=data.state==='capacity'?'Todas as salas estão ocupadas neste momento.':'Procurando alguém do outro lado para conversar.';$('#wait-detail').textContent=data.state==='capacity'?'Você está aguardando uma vaga.':'Você está na fila. Pode ficar por aqui.'}
async function begin(){if(busy)return;busy=true;$('#enter').disabled=true;$('#entry-error').textContent='';const token=++sessionToken;stop();room=null;try{if(live)await connect();screen('waiting');if(live){await seek(token);if(!room&&token===sessionToken)poll=setInterval(async()=>{if(busy)return;busy=true;try{await seek(token)}catch(e){$('#wait-copy').textContent='A conexão oscilou. Tentando novamente…'}finally{busy=false}},4000)}else{$('#wait-copy').textContent='O seu próximo encontro começa por aqui.';$('#wait-detail').textContent='Prévia sem usuários reais. Explore uma sala de exemplo.'}}catch(e){screen('landing');showError(e)}finally{busy=false;$('#enter').disabled=false}}
$('#entry-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);const nickname=form.get('nickname').trim();if(nickname.length<2){showError({message:'Escolha um apelido com pelo menos 2 caracteres.'});return}profile={nickname,side:form.get('side')};begin()};
function demo(){stop();room={id:'demo',expires_at:new Date(Date.now()+30*60000).toISOString()};profile??={nickname:'Você',side:'left'};prepareChat('Alex · exemplo',profile.side==='left'?'right':'left');demoTasks.push(setTimeout(()=>message('Oi! A gente provavelmente discorda de algumas coisas. Mas acho que dá para ter uma boa conversa 🙂'),700));demoTasks.push(setTimeout(()=>message('Qual assunto você gostaria de entender melhor do outro lado?'),1700))}
$('#demo-enter').onclick=demo;$('#wait-demo').onclick=demo;
$('#cancel-wait').onclick=async()=>{++sessionToken;stop();screen('landing');if(live&&db){try{const {error}=await db.rpc('leave_session');check(error)}catch(e){showError(e)}}};
function finish(text){stop();$('#chat-ended').hidden=false;$('#end-copy').textContent=text;$('#message-input').disabled=true;$('#message-form button').disabled=true}
async function leave(){if(live){const {error}=await db.rpc('leave_session');check(error)}finish('Você encerrou a conversa. Cada encontro é uma nova oportunidade.')}
$('#leave').onclick=()=>{modal('<h2>Encerrar esta conversa?</h2><p>Você pode buscar outra pessoa em seguida.</p><button class="primary" id="confirm-leave">Encerrar conversa ↗</button>');$('#confirm-leave').onclick=async()=>{try{await leave();$('#info-dialog').close()}catch(e){$('#confirm-leave').textContent='Falha ao encerrar. Tente novamente.'}}};
$('#back-home').onclick=()=>{room=null;screen('landing')};$('#next-chat').onclick=()=>{room=null;begin()};
$('#message-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#message-form').requestSubmit()}};
$('#message-form').onsubmit=async e=>{e.preventDefault();const input=$('#message-input');const text=input.value.trim();if(!text||!room||!$('#chat-ended').hidden)return;if(Date.now()>=Date.parse(room.expires_at)){countdown();return}if(Date.now()-lastSend<1000){$('#chat-status').textContent='Espere um instante antes de enviar outra mensagem.';return}lastSend=Date.now();const button=$('#message-form button');button.disabled=true;try{if(live){const {data,error}=await db.rpc('send_message',{p_room:room.id,p_body:text});check(error);receive(data)}else{message(text,true);$('#chat-status').textContent='Demonstração · mensagens recebidas são exemplos.'}input.value='';input.focus()}catch(e){$('#chat-status').textContent='Não foi possível enviar: '+e.message}finally{button.disabled=!$('#chat-ended').hidden}};
$('#report').onclick=()=>{if(!$('#chat-ended').hidden)return;modal('<h2>Denunciar e bloquear</h2><p>A conversa será encerrada e essa identidade não será pareada com você novamente.</p><label for="reason">Motivo</label><select id="reason"><option>Ataques pessoais ou discriminação</option><option>Ameaça ou exposição de dados</option><option>Spam ou comportamento inadequado</option></select><label for="details">Detalhes (opcional)</label><textarea id="details" maxlength="500" placeholder="O que aconteceu?"></textarea><button class="primary" id="send-report">Denunciar e encerrar ↗</button>');$('#send-report').onclick=async()=>{const btn=$('#send-report');btn.disabled=true;try{if(live){const {error}=await db.rpc('report_room',{p_room:room.id,p_reason:$('#reason').value,p_details:$('#details').value});check(error)}finish(live?'Denúncia registrada. Esta identidade foi bloqueada para novos encontros.':'Demonstração encerrada. Nenhuma denúncia real foi enviada.');$('#info-dialog').close()}catch(e){btn.textContent='Falha ao denunciar. Tente novamente.';btn.disabled=false}}};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&room&&$('#chat-ended').hidden){countdown();if(live)syncRoom().catch(()=>{})}});
